#!/usr/bin/env node

import { createServer, configOptions, formatServerState, options } from '../dist/esm/index.js';

function usage() {

    console.log(`Usage: dhcpd --range 192.168.1.10-192.168.1.99 [options]

Output:
  -v, --verbose  Print DHCP state transitions
  -vv, --debug   Print state transitions and structured debug logs
  -h, --help     Show this help`);
}

const args = process.argv.slice(2);
const config = {};
const forceOptions = [];
let verbose = false;
let debug = false;

for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];

    if (argument === '--help' || argument === '-h') {
        usage();
        process.exit(0);
    }
    if (argument === '--verbose' || argument === '-v') {
        verbose = true;
        continue;
    }
    if (argument === '--debug' || argument === '-vv') {
        verbose = true;
        debug = true;
        continue;
    }
    if (!argument.startsWith('--')) {
        throw new Error(`Unexpected argument: ${argument}`);
    }

    const key = argument.slice(2);
    const values = [];

    while (args[index + 1] && !args[index + 1].startsWith('--')) {
        values.push(args[index += 1]);
    }
    if (values.length === 0) {
        throw new Error(`Option --${key} requires a value`);
    }
    if (key === 'range') {
        config.range = values[0].split('-');
    } else if (configOptions[key] !== undefined) {
        const definition = options[configOptions[key]];
        const numeric = definition.type?.startsWith('UInt') || definition.type?.startsWith('Int');

        if (definition.type === 'Bool') {
            config[key] = /^(1|true|yes|on)$/i.test(values[0]);
        } else if (numeric) {
            config[key] = values.length === 1 ? Number(values[0]) : values.map(Number);
        } else {
            config[key] = definition.type === 'IPs' || values.length > 1 ? values : values[0];
        }
        if (configOptions[key] <= 254 && definition.type) {
            forceOptions.push(key);
        }
    } else {
        throw new Error(`Unknown DHCP option: ${key}`);
    }
}

if (!config.range || config.range.length !== 2) {
    usage();
    process.exit(1);
}

config.forceOptions = forceOptions;
config.logLevel = debug ? 'debug' : 'silent';

const server = createServer(config);

if (verbose) {
    server.on('state', (state, packet) => {

        for (const line of formatServerState(state, packet, server.leases.size)) {
            console.log(line);
        }
    });
}
server.on('error', (error) => console.error(`Error: ${error.message}`));
server.listen();

for (const signal of ['SIGINT', 'SIGTERM']) {
    process.on(signal, () => server.close(() => process.exit(0)));
}
